#!/usr/bin/env bash
# Single-source the deterministic scripts AND the shared reference docs. Canonical = prism-all/*.
# prism-codex and prism receive generated copies. Run after editing a canonical.
#
# parse-findings.js, verify-evidence.js, references/{record-v2,redteam-lens,design-lenses}.md are
# byte-identical across skills → plain copy.
# references/codex-invocation.md exists only in the Codex-backed skills; prism-codex gets a
# name-rewritten copy.
# verify-independence.js differs per skill (SELF_NAME / REQUIRED_FILES / PREREQUISITES), so it is
# generated by a sed/perl rewrite of the canonical rather than copied verbatim.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"

IDENTICAL=(parse-findings.js verify-evidence.js references/record-v2.md references/redteam-lens.md references/design-lenses.md)

# 1. Identical files: copy verbatim.
mkdir -p "$here/prism-codex/references" "$here/prism/references"
for f in "${IDENTICAL[@]}"; do
  cp "$here/prism-all/$f" "$here/prism-codex/$f"
  cp "$here/prism-all/$f" "$here/prism/$f"
done

# 2. Codex invocation contract: prism-codex only, name-rewritten. prism is Claude-only.
sed 's/prism-all/prism-codex/g' "$here/prism-all/references/codex-invocation.md" > "$here/prism-codex/references/codex-invocation.md"
rm -f "$here/prism/references/codex-invocation.md"

# 3. verify-independence.js: prism-codex = rename only; prism = rename + drop Codex prereq + drop codex-invocation.md.
sed 's/prism-all/prism-codex/g' "$here/prism-all/verify-independence.js" > "$here/prism-codex/verify-independence.js"
sed 's/prism-all/prism/g' "$here/prism-all/verify-independence.js" \
  | perl -0pe "s/const PREREQUISITES = \[\n  \{ cmd: 'codex --version', label: 'Codex CLI', fatal: true, min: '0\.125\.0' \},\n\];/const PREREQUISITES = []; \/\/ prism is Claude-only — no external CLI prerequisite/" \
  | perl -pe "s/, 'references\/codex-invocation.md'//" \
  > "$here/prism/verify-independence.js"

# 4. Verify the sync actually holds (integrity gate — catches silent drift).
fail=0
for f in "${IDENTICAL[@]}"; do
  for d in prism-codex prism; do
    if ! diff -q "$here/prism-all/$f" "$here/$d/$f" >/dev/null; then
      echo "DRIFT: $d/$f != prism-all/$f" >&2; fail=1
    fi
  done
done
if ! diff -q <(sed 's/prism-all/prism-codex/g' "$here/prism-all/references/codex-invocation.md") "$here/prism-codex/references/codex-invocation.md" >/dev/null; then
  echo "DRIFT: prism-codex/references/codex-invocation.md" >&2; fail=1
fi
[ "$fail" = 0 ] && echo "synced + verified: ${IDENTICAL[*]}, references/codex-invocation.md, verify-independence.js -> prism-codex, prism" || { echo "sync FAILED" >&2; exit 1; }
